export function shuffle(items,random=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
export function makeSession(bank,{audience,difficulty,count=5,startId='',random=Math.random}){const pool=bank.filter(q=>q.audience===audience&&q.difficulty===difficulty);if(!pool.length)throw Error('這個關卡還沒有題目。');if(difficulty==='boss'){const selected=pool.find(q=>q.id===startId)||shuffle(pool,random)[0];return pool.filter(q=>q.group===selected.group).sort((a,b)=>a.round-b.round)}const first=pool.find(q=>q.id===startId);return [...(first?[first]:[]),...shuffle(pool.filter(q=>q!==first),random)].slice(0,count)}
export function grade(question,optionId){return optionId===question.answer}
export function sessionSummary(history){const answered=history.filter(x=>!x.skipped);const correct=answered.filter(x=>x.correct).length;return{correct,answered:answered.length,skipped:history.length-answered.length,accuracy:answered.length?Math.round(correct/answered.length*100):0}}
